#!/usr/bin/env python3
import csv
import json
from pathlib import Path

ROOT = Path('/root')
CATALOG_PATH = ROOT / 'program_catalog.json'
COOLER_COST_PATH = ROOT / 'cooler_cost.csv'
CONTRACT_PAYMENT_PATH = ROOT / 'contract_payment.csv'
SITE_OVERRIDES_PATH = ROOT / 'site_overrides.csv'
ANALYSIS_PATH = ROOT / 'oncocooler_analysis.json'
SUMMARY_PATH = ROOT / 'oncocooler_summary.md'


def money(value):
    return round(float(value) + 1e-9, 2)


def load_csv(path):
    with path.open(newline='') as handle:
        return list(csv.DictReader(handle))


def load_review_programs(catalog):
    programs = []
    for group in catalog.get('service_groups', []):
        for program in group.get('programs', []):
            if program.get('review_flag') == 'review':
                item = dict(program)
                item['service_group'] = group.get('group_name')
                programs.append(item)
    return programs


def build_payment_map(payment_rows, programs_by_label):
    payment_by_code = {}
    for row in payment_rows:
        label = row['program_label']
        program = programs_by_label.get(label)
        if program is None:
            continue
        code = program['program_code']
        if code in payment_by_code:
            raise ValueError(f'Multiple payment rows matched in-scope program {code}')
        payment_by_code[code] = float(row['payment_per_dispatch_per_site_usd'])
    return payment_by_code


def build_active_site_map(override_rows):
    best_approved = {}
    for row in override_rows:
        if row['approval_state'] != 'approved':
            continue
        code = row['program_code']
        version = int(row['version_no'])
        if code not in best_approved or version > best_approved[code]['version_no']:
            best_approved[code] = {
                'version_no': version,
                'active_sites': int(row['active_sites']),
            }
    return {code: value['active_sites'] for code, value in best_approved.items()}


def model_financials(program, active_sites, payment, cooler_cost, days_per_dispatch, dispatches_per_year):
    annual_drug_cost = (
        float(program['acquisition_cost_per_1000_units_usd'])
        * active_sites
        * float(program['units_per_day'])
        * days_per_dispatch
        * dispatches_per_year
        / 1000
    )
    annual_cooler_cost = cooler_cost * dispatches_per_year
    annual_revenue = payment * active_sites * dispatches_per_year
    annual_margin = annual_revenue - annual_drug_cost - annual_cooler_cost
    return {
        'annual_drug_cost_usd': money(annual_drug_cost),
        'annual_cooler_cost_usd': money(annual_cooler_cost),
        'annual_revenue_usd': money(annual_revenue),
        'annual_margin_usd': money(annual_margin),
    }


def main():
    with CATALOG_PATH.open() as handle:
        catalog = json.load(handle)

    cooler_rows = load_csv(COOLER_COST_PATH)
    payment_rows = load_csv(CONTRACT_PAYMENT_PATH)
    override_rows = load_csv(SITE_OVERRIDES_PATH)

    programs = load_review_programs(catalog)
    programs_by_label = {}
    for program in programs:
        labels = [program['program_name'], *program.get('known_labels', [])]
        for label in labels:
            programs_by_label[label] = program

    payment_by_code = build_payment_map(payment_rows, programs_by_label)
    active_sites_by_code = build_active_site_map(override_rows)
    cooler_cost_by_type = {
        row['cooler_type']: float(row['cooler_cost_usd'])
        for row in cooler_rows
    }

    output_programs = []
    for program in sorted(programs, key=lambda p: p['program_code']):
        code = program['program_code']
        if code not in payment_by_code:
            raise ValueError(f'No in-scope payment row matched program {code}')
        cooler_type = program['cooler_type']
        if cooler_type not in cooler_cost_by_type:
            raise ValueError(f'No cooler cost row matched cooler type {cooler_type}')

        active_sites = active_sites_by_code.get(code, int(program['default_active_sites']))
        payment = payment_by_code[code]
        cooler_cost = cooler_cost_by_type[cooler_type]

        ten_day = model_financials(program, active_sites, payment, cooler_cost, 10, 36)
        twenty_day = model_financials(program, active_sites, payment, cooler_cost, 20, 18)
        margin_difference = money(twenty_day['annual_margin_usd'] - ten_day['annual_margin_usd'])

        output_programs.append({
            'program_code': code,
            'program_name': program['program_name'],
            'service_group': program['service_group'],
            'active_sites': active_sites,
            'payment_per_dispatch_per_site_usd': money(payment),
            'cooler_type': cooler_type,
            'cooler_cost_usd': money(cooler_cost),
            'annual_drug_cost_10_day_usd': ten_day['annual_drug_cost_usd'],
            'annual_cooler_cost_10_day_usd': ten_day['annual_cooler_cost_usd'],
            'annual_revenue_10_day_usd': ten_day['annual_revenue_usd'],
            'annual_margin_10_day_usd': ten_day['annual_margin_usd'],
            'annual_drug_cost_20_day_usd': twenty_day['annual_drug_cost_usd'],
            'annual_cooler_cost_20_day_usd': twenty_day['annual_cooler_cost_usd'],
            'annual_revenue_20_day_usd': twenty_day['annual_revenue_usd'],
            'annual_margin_20_day_usd': twenty_day['annual_margin_usd'],
            'annual_margin_difference_20_minus_10_usd': margin_difference,
        })

    total_10 = money(sum(p['annual_margin_10_day_usd'] for p in output_programs))
    total_20 = money(sum(p['annual_margin_20_day_usd'] for p in output_programs))
    total_difference = money(sum(p['annual_margin_difference_20_minus_10_usd'] for p in output_programs))
    absolute_difference = money(abs(total_difference))

    decision = 'move_to_20_day' if absolute_difference < 10000 else 'keep_10_day'
    if decision == 'move_to_20_day':
        justification = (
            f'Absolute total annual margin difference is ${absolute_difference:,.2f}, '
            'which is below the $10,000 threshold.'
        )
    else:
        justification = (
            f'Absolute total annual margin difference is ${absolute_difference:,.2f}, '
            'which is at or above the $10,000 threshold.'
        )

    analysis = {
        'assumptions': {
            'program_filter': 'Only programs with review_flag == "review" are included.',
            'payment_matching': 'contract_payment.program_label is matched to program_name or any known_labels entry for in-scope programs.',
            'active_sites': 'Use the approved site_overrides row with the highest version_no; otherwise use default_active_sites.',
            'cooler_cost': 'annual_cooler_cost = cooler_cost_usd * dispatches_per_year.',
            'currency_rounding': 'All currency values are rounded to 2 decimal places.',
            'sort_order': 'Programs are sorted by program_code ascending.',
            'ten_day_model': {
                'days_per_dispatch': 10,
                'dispatches_per_year': 36,
            },
            'twenty_day_model': {
                'days_per_dispatch': 20,
                'dispatches_per_year': 18,
            },
            'decision_rule': 'If absolute_total_margin_difference_usd < 10000, decision is move_to_20_day; otherwise keep_10_day.',
        },
        'programs': output_programs,
        'totals': {
            'total_annual_margin_10_day_usd': total_10,
            'total_annual_margin_20_day_usd': total_20,
            'total_annual_margin_difference_20_minus_10_usd': total_difference,
            'absolute_total_margin_difference_usd': absolute_difference,
        },
        'recommendation': {
            'decision': decision,
            'justification': justification,
        },
    }

    with ANALYSIS_PATH.open('w') as handle:
        json.dump(analysis, handle, indent=2)
        handle.write('\n')

    summary_lines = [
        '# OncoCooler Margin Summary',
        f'Total 10-day margin in USD: ${total_10:,.2f}',
        f'Total 20-day margin in USD: ${total_20:,.2f}',
        f'Absolute difference in USD: ${absolute_difference:,.2f}',
        f'Decision: {decision}',
    ]
    SUMMARY_PATH.write_text('\n'.join(summary_lines) + '\n')


if __name__ == '__main__':
    main()

